     1 │ // 激活码注册 + 设备绑定 + token 颁发
     2 │ package main
     3 │ 
     4 │ import (
     5 │ 	"encoding/json"
     6 │ 	"net/http"
     7 │ 	"strings"
     8 │ )
     9 │ 
    10 │ type registerRequest struct {
    11 │ 	Code     string `json:"code"`
    12 │ 	DeviceID string `json:"device_id"`
    13 │ }
    14 │ 
    15 │ type registerResponse struct {
    16 │ 	Token     string `json:"token"`
    17 │ 	DeviceID  string `json:"device_id"`
    18 │ 	ExpiresAt int64  `json:"expires_at"` // 0 = 永久
    19 │ 	Code      string `json:"code"`
    20 │ }
    21 │ 
    22 │ // handleRegister 激活码注册：校验激活码 → 绑定设备 → 颁发 token
    23 │ func handleRegister(store *Store) http.HandlerFunc {
    24 │ 	return func(w http.ResponseWriter, r *http.Request) {
    25 │ 		if r.Method != http.MethodPost {
    26 │ 			writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
    27 │ 			return
    28 │ 		}
    29 │ 		// 注册接口按 IP 限流：10 次/分
    30 │ 		ip := clientIP(r)
    31 │ 		if !registerLimiter.Allow("reg:"+ip) {
    32 │ 			writeJSON(w, http.StatusTooManyRequests, map[string]string{"error": "请求过于频繁，请稍后再试"})
    33 │ 			return
    34 │ 		}
    35 │ 
    36 │ 		var req registerRequest
    37 │ 		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
    38 │ 			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "无效请求体"})
    39 │ 			return
    40 │ 		}
    41 │ 		req.Code = strings.ToUpper(strings.TrimSpace(req.Code))
    42 │ 		req.DeviceID = strings.TrimSpace(req.DeviceID)
    43 │ 		if req.Code == "" || req.DeviceID == "" {
    44 │ 			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "缺少 code 或 device_id"})
    45 │ 			return
    46 │ 		}
    47 │ 		if len(req.DeviceID) > 128 {
    48 │ 			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "device_id 过长"})
    49 │ 			return
    50 │ 		}
    51 │ 
    52 │ 		code, err := store.GetCode(req.Code)
    53 │ 		if err != nil {
    54 │ 			writeJSON(w, http.StatusForbidden, map[string]string{"error": "激活码无效"})
    55 │ 			return
    56 │ 		}
    57 │ 		if !code.IsValid() {
    58 │ 			writeJSON(w, http.StatusForbidden, map[string]string{"error": "激活码已失效（过期或已吊销）"})
    59 │ 			return
    60 │ 		}
    61 │ 
    62 │ 		token, err := store.AddDevice(req.Code, req.DeviceID)
    63 │ 		if err != nil {
    64 │ 			writeJSON(w, http.StatusForbidden, map[string]string{"error": err.Error()})
    65 │ 			return
    66 │ 		}
    67 │ 		_ = store.MarkCodeUsed(req.Code)
    68 │ 
    69 │ 		writeJSON(w, http.StatusOK, registerResponse{
    70 │ 			Token:     token,
    71 │ 			DeviceID:  req.DeviceID,
    72 │ 			ExpiresAt: code.ExpiresAt,
    73 │ 			Code:      req.Code,
    74 │ 		})
    75 │ 	}
    76 │ }
    77 │ 
    78 │ // handleAdminGenCode 管理接口：生成激活码（需 X-Admin-Key 头）
    79 │ func handleAdminGenCode(store *Store) http.HandlerFunc {
    80 │ 	return func(w http.ResponseWriter, r *http.Request) {
    81 │ 		if r.Method != http.MethodPost {
    82 │ 			writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
    83 │ 			return
    84 │ 		}
    85 │ 		if !checkAdminKey(r) {
    86 │ 			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "管理密钥错误"})
    87 │ 			return
    88 │ 		}
    89 │ 
    90 │ 		var req struct {
    91 │ 			Days int    `json:"days"` // 0 = 永久
    92 │ 			Note string `json:"note"`
    93 │ 			N    int    `json:"n"` // 生成数量，默认 1
    94 │ 		}
    95 │ 		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
    96 │ 			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "无效请求体"})
    97 │ 			return
    98 │ 		}
    99 │ 		if req.N <= 0 || req.N > 100 {
   100 │ 			req.N = 1
   101 │ 		}
   102 │ 		codes := make([]string, 0, req.N)
   103 │ 		for i := 0; i < req.N; i++ {
   104 │ 			c, err := GenCode()
   105 │ 			if err != nil {
   106 │ 				writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "生成失败"})
   107 │ 				return
   108 │ 			}
   109 │ 			if err := store.CreateCode(c, req.Days, req.Note); err != nil {
   110 │ 				writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "写入失败"})
   111 │ 				return
   112 │ 			}
   113 │ 			codes = append(codes, c)
   114 │ 		}
   115 │ 		writeJSON(w, http.StatusOK, map[string]interface{}{"codes": codes})
   116 │ 	}
   117 │ }
   118 │ 
   119 │ // handleAdminList 管理接口：查看激活码与绑定设备（需 X-Admin-Key 头）
   120 │ func handleAdminList(store *Store) http.HandlerFunc {
   121 │ 	return func(w http.ResponseWriter, r *http.Request) {
   122 │ 		if !checkAdminKey(r) {
   123 │ 			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "管理密钥错误"})
   124 │ 			return
   125 │ 		}
   126 │ 		// 单条 JOIN 查询，避免打开 rows 后再发起子查询（MaxOpenConns=1 会死锁）
   127 │ 		rows, err := store.db.Query(`SELECT c.code, c.status, c.expires_at, c.created_at, c.note, COUNT(d.device_id)
   128 │ 			FROM activation_codes c LEFT JOIN devices d ON d.code = c.code
   129 │ 			GROUP BY c.code ORDER BY c.created_at DESC LIMIT 200`)
   130 │ 		if err != nil {
   131 │ 			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "查询失败"})
   132 │ 			return
   133 │ 		}
   134 │ 		defer rows.Close()
   135 │ 
   136 │ 		type codeRow struct {
   137 │ 			Code      string `json:"code"`
   138 │ 			Status    string `json:"status"`
   139 │ 			ExpiresAt int64  `json:"expires_at"`
   140 │ 			CreatedAt int64  `json:"created_at"`
   141 │ 			Note      string `json:"note"`
   142 │ 			Devices   int    `json:"devices"`
   143 │ 		}
   144 │ 		codes := []codeRow{}
   145 │ 		for rows.Next() {
   146 │ 			var c codeRow
   147 │ 			if err := rows.Scan(&c.Code, &c.Status, &c.ExpiresAt, &c.CreatedAt, &c.Note, &c.Devices); err != nil {
   148 │ 				continue
   149 │ 			}
   150 │ 			codes = append(codes, c)
   151 │ 		}
   152 │ 		writeJSON(w, http.StatusOK, map[string]interface{}{"codes": codes})
   153 │ 	}
   154 │ }
