     1 │ // HMAC 签名校验 + 防重放（时间戳窗口 + nonce 一次性）
     2 │ package main
     3 │ 
     4 │ import (
     5 │ 	"crypto/hmac"
     6 │ 	"crypto/sha256"
     7 │ 	"encoding/hex"
     8 │ 	"fmt"
     9 │ 	"io"
    10 │ 	"net/http"
    11 │ 	"strconv"
    12 │ 	"strings"
    13 │ 	"sync"
    14 │ 	"time"
    15 │ )
    16 │ 
    17 │ const maxTimestampSkew = 5 * 60 // 时间戳允许偏差：5 分钟
    18 │ 
    19 │ // nonceStore 防重放：记录已用过的 nonce，超过 TTL 自动清理
    20 │ type nonceStore struct {
    21 │ 	mu   sync.Mutex
    22 │ 	seen map[string]time.Time
    23 │ 	ttl  time.Duration
    24 │ }
    25 │ 
    26 │ func newNonceStore(ttl time.Duration) *nonceStore {
    27 │ 	ns := &nonceStore{seen: map[string]time.Time{}, ttl: ttl}
    28 │ 	go func() {
    29 │ 		ticker := time.NewTicker(ttl / 2)
    30 │ 		defer ticker.Stop()
    31 │ 		for range ticker.C {
    32 │ 			ns.cleanup()
    33 │ 		}
    34 │ 	}()
    35 │ 	return ns
    36 │ }
    37 │ 
    38 │ func (ns *nonceStore) checkAndSet(nonce string) bool {
    39 │ 	ns.mu.Lock()
    40 │ 	defer ns.mu.Unlock()
    41 │ 	if _, ok := ns.seen[nonce]; ok {
    42 │ 		return false // 已用过 = 重放
    43 │ 	}
    44 │ 	ns.seen[nonce] = time.Now()
    45 │ 	return true
    46 │ }
    47 │ 
    48 │ func (ns *nonceStore) cleanup() {
    49 │ 	ns.mu.Lock()
    50 │ 	defer ns.mu.Unlock()
    51 │ 	cutoff := time.Now().Add(-ns.ttl)
    52 │ 	for k, v := range ns.seen {
    53 │ 		if v.Before(cutoff) {
    54 │ 			delete(ns.seen, k)
    55 │ 		}
    56 │ 	}
    57 │ }
    58 │ 
    59 │ // verifySignature 校验请求签名。
    60 │ // 客户端签名内容：HMAC-SHA256(key=token, msg=method\npath\ntimestamp\nnonce\nbodySHA256)
    61 │ // 签名正确且时间戳在窗口内且 nonce 未被用过 → 通过。
    62 │ // 校验通过后恢复 r.Body（后续 handler 仍需读取）。
    63 │ func verifySignature(r *http.Request, token string) (bool, string) {
    64 │ 	ts := r.Header.Get("X-Timestamp")
    65 │ 	nonce := r.Header.Get("X-Nonce")
    66 │ 	sign := r.Header.Get("X-Sign")
    67 │ 	if ts == "" || nonce == "" || sign == "" {
    68 │ 		return false, "缺少签名头 (X-Timestamp/X-Nonce/X-Sign)"
    69 │ 	}
    70 │ 
    71 │ 	// 1. 时间戳窗口
    72 │ 	t, err := strconv.ParseInt(ts, 10, 64)
    73 │ 	if err != nil {
    74 │ 		return false, "时间戳非法"
    75 │ 	}
    76 │ 	now := time.Now().Unix()
    77 │ 	if now-t > maxTimestampSkew || t-now > maxTimestampSkew {
    78 │ 		return false, "时间戳超出窗口"
    79 │ 	}
    80 │ 
    81 │ 	// 2. 防重放
    82 │ 	if !globalNonceStore.checkAndSet(nonce) {
    83 │ 		return false, "重放请求"
    84 │ 	}
    85 │ 
    86 │ 	// 3. 签名校验
    87 │ 	body, err := io.ReadAll(r.Body)
    88 │ 	if err != nil {
    89 │ 		return false, "读取请求体失败"
    90 │ 	}
    91 │ 	r.Body = io.NopCloser(strings.NewReader(string(body)))
    92 │ 	bodyHash := sha256.Sum256(body)
    93 │ 	msg := fmt.Sprintf("%s\n%s\n%s\n%s\n%s", r.Method, r.URL.Path, ts, nonce, hex.EncodeToString(bodyHash[:]))
    94 │ 	mac := hmac.New(sha256.New, []byte(token))
    95 │ 	mac.Write([]byte(msg))
    96 │ 	expected := hex.EncodeToString(mac.Sum(nil))
    97 │ 	if !hmac.Equal([]byte(expected), []byte(sign)) {
    98 │ 		return false, "签名不匹配"
    99 │ 	}
   100 │ 	return true, ""
   101 │ }
